    d._v = ch
    var f = faces(d)
    var old = f.fc.textContent                    // 翻页前实际显示值（前脸），静止态与上半一致
    f.sc.textContent = ch                         // 静止上半：翻页瞬间立即变为新值
    f.fn.textContent = ch                         // 后脸（下半）：预置新值
    f.fc.textContent = old                        // 前脸（上半）：保持旧值，随翻板翻走
